source='''from collections import Counter, deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]
    seen = set()
    labels = {}
    components = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == background or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            component = []
            while q:
                y, x = q.popleft()
                component.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and (ny, nx) not in seen and grid[ny][nx] == color:
                        seen.add((ny, nx))
                        q.append((ny, nx))
            components.append((color, component))
            if len(component) > 1:
                for y, x in component:
                    labels[(y, x)] = color
    out = [[background for _ in range(w)] for _ in range(h)]
    for (y, x), color in labels.items():
        out[y][x] = color
    for color, component in components:
        if len(component) != 1:
            continue
        y, x = component[0]
        neighbors = [out[ny][nx] for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1))
                     if 0 <= (ny := y + dy) < h and 0 <= (nx := x + dx) < w and out[ny][nx] != background]
        if neighbors:
            out[y][x] = Counter(neighbors).most_common(1)[0][0]
    return out
'''
